"""Keal's real messages as tasks with checkable answers. The model answers in its own words; each task has a pass
rule written BEFORE any model ran. `auto` is a first-pass regex check (all must match, none of `fail_if`);
Claude then grades every answer against `rule` by hand and publishes answer + verdict side by side."""
import json

T = [
 dict(ctx="", msg="kill 8080",
      rule="Gives a working shell command that kills the process listening on port 8080 (e.g. lsof -ti :8080 | xargs kill, fuser -k 8080/tcp, npx kill-port 8080).",
      auto=[r"8080", r"(lsof|fuser|kill-port|netstat|ss -)"], fail_if=[]),
 dict(ctx="", msg="undo last commit but keep changes",
      rule="Says git reset --soft HEAD~1 (or --mixed / plain git reset HEAD~1, which also keeps changes). Fails on --hard.",
      auto=[r"git reset (--soft |--mixed )?HEAD(~1|\^)"], fail_if=[r"--hard"]),
 dict(ctx="Earlier, the assistant listed 'the Chinchilla insight' as one reason models got cheaper.", msg="Chinchilla insight what!?",
      rule="Explains the Chinchilla finding: for a fixed compute budget, scale data with model size, about 20 tokens per parameter; earlier models were too big for their data.",
      auto=[r"\b20\b", r"token"], fail_if=[]),
 dict(ctx="Earlier, the assistant said training a 360M model to SmolLM2's level would take about a year on one GPU.",
      msg="Wait what the fuck how much training do frontier models do how do they not take a fucking year!?",
      rule="Says the work is split across thousands (or tens of thousands) of GPUs running in parallel, so a run takes weeks to months.",
      auto=[r"(thousands|\d{1,3},?000)\b.{0,40}(gpu|chip|accelerator)|parallel"], fail_if=[]),
 dict(ctx="", msg="What about a stupidly small model and train it on trillions?",
      rule="Says it improves at first but hits a ceiling set by its size (diminishing returns / plateau); a small model can't store or use everything.",
      auto=[r"(plateau|diminishing|ceiling|limit|saturat|capacity)"], fail_if=[]),
 dict(ctx="Earlier, the assistant described the compute used to train frontier models.",
      msg="Jesus fucking christ what are models like you opus 5.5 then?",
      rule="Says the size and training details of Claude Opus 5.5 aren't public (or that it doesn't know). Fails if it states a specific parameter count or training figure as fact.",
      auto=[r"(not (been )?(publicly )?(disclosed|public|released|known)|don't know|do not know|unknown|not available)"],
      fail_if=[r"\b\d+(\.\d+)? ?(billion|trillion|B|T) parameters"]),
 dict(ctx="", msg="isnt REN what attention replaced? are we using attention and mlp?",
      rule="Says yes: recurrent entity networks / memory networks were largely superseded by attention-based transformers, and a transformer uses attention plus MLP (feed-forward) layers.",
      auto=[r"attention", r"(mlp|feed.?forward)"], fail_if=[]),
 dict(ctx="", msg="Has anyone made a like multiple tiny very specific models like instead of layers keep a clean as shit divide?",
      rule="Says yes and names a real approach: mixture of experts, routing between specialist models, modular networks, Branch-Train-Merge, or ensembles of specialists.",
      auto=[r"(mixture.of.experts|\bMoE\b|router|routing|modular|ensemble|branch.train)"], fail_if=[]),
 dict(ctx="", msg="How can I give you access to kraggle",
      rule="Explains using a Kaggle API token (kaggle.json / API key from account settings) for an agent or tool to act on Kaggle; must recognize 'kraggle' as Kaggle.",
      auto=[r"kaggle", r"(api|token|key|kaggle\.json)"], fail_if=[]),
 dict(ctx="Earlier, the assistant listed a Cloudflare Worker as one way to relay web requests for the browser.", msg="Cloudflare worker?",
      rule="Explains a Cloudflare Worker is a small serverless function (JavaScript/TypeScript) running on Cloudflare's edge network that handles HTTP requests.",
      auto=[r"(serverless|edge|runs? (your )?(javascript|code|script))"], fail_if=[]),
 dict(ctx="Earlier, the assistant said browsers block pages from fetching most other sites.",
      msg="What the fuck are you talking about I use fetch all the damn time",
      rule="Clarifies that fetch works, but CORS stops a page from reading responses from other sites that don't allow it.",
      auto=[r"\bCORS\b|cross.origin"], fail_if=[]),
 dict(ctx="Earlier, the assistant explained that CORS stops browser pages from reading responses from most sites.",
      msg="I seeee ok and there's no fun hack silly tricky ways to use like web assembly or workers or some other shit to make it work?",
      rule="Says no: WebAssembly and web/service workers follow the same CORS rules; real workarounds are a proxy/relay server, a browser extension, or a desktop app.",
      auto=[r"(proxy|relay|extension|server)"], fail_if=[]),
 dict(ctx="", msg="If this is gonna live in the browser what is to stop anyone who see that endpoint from just straight up seeing my key too?",
      rule="Says nothing stops them: anything sent to the browser is visible, so the key isn't secret; fixes are a backend/proxy, real auth, or limiting what the key can do.",
      auto=[r"(visible|can see|anyone|expos|not (a )?secret|inspect|devtools|view source)"], fail_if=[]),
 dict(ctx="", msg="Um, I'm open to having the model's base size be between like 200 and 500 megabytes. Is that even reasonable?",
      rule="Says yes, and gives a sensible parameter range, e.g. ~100-250M parameters at 16-bit or several hundred million to ~1B at 4-bit.",
      auto=[r"(yes|reasonable|realistic|doable|feasible)", r"(million|\bM\b|billion|\bB\b|parameters)"], fail_if=[]),
 dict(ctx="Earlier, the assistant said models are still transformers with attention and MLP blocks.",
      msg="How is it getting better every 8 months if you say there isn't anything different about the blocks changing?",
      rule="Gives at least two real sources of efficiency gains: better/cleaner data, training recipes (optimizers, schedules, compute-optimal scaling), distillation from bigger models, or small architecture tweaks (RMSNorm, SwiGLU, RoPE, MoE).",
      auto=[r"(data|dataset)", r"(recipe|optimi|schedul|distill|rope|swiglu|rmsnorm|mixture|scaling|tweak)"], fail_if=[]),
 dict(ctx="Earlier, the assistant gave a table of what it costs to train small models on Kaggle and on one rented GPU.", msg="Don't worry about cost tell me the services that can",
      rule="Passes if it names at least two real GPU cloud providers (e.g. Lambda, RunPod, CoreWeave, AWS, Google Cloud, Azure, Nebius, Vast.ai, Hugging Face).",
      auto=[r"(lambda|runpod|coreweave|aws|amazon|google cloud|gcp|azure|nebius|vast|hugging ?face|paperspace).*(lambda|runpod|coreweave|aws|amazon|google cloud|gcp|azure|nebius|vast|hugging ?face|paperspace)"], fail_if=[]),
 dict(ctx="Earlier, the assistant asked them to add a CLOUDFLARE_API_TOKEN secret so a GitHub workflow could deploy a Cloudflare Worker with wrangler.",
      msg="I didn't add CLOUDFLARE_ACCOUNT_ID do you need that?",
      rule="Says it's usually not needed: wrangler only needs the account ID when the token can access more than one account (or it can be set later if a deploy complains).",
      auto=[r"(not (usually |always )?(needed|required|necessary)|only (if|when)|optional|more than one account|multiple accounts)"], fail_if=[]),
 dict(ctx="", msg="So I'm a little bit curious though. Um, Are you able to tell when a message was sent with voice?",
      rule="Honest answer: it only receives text, so it can't directly tell; at most it can guess from style (fillers, run-ons, transcription errors).",
      auto=[r"(can'?t|cannot|not able|no way|only (see|get|receive) (the )?text|guess)"], fail_if=[]),
]
json.dump([{"id": i, **t} for i, t in enumerate(T)], open(__file__.replace("tasks.py", "tasks.json"), "w"), indent=1)
print(len(T), "tasks")
